const fruits = [
  { name: "maçã", color: "red" },
  { name: "banana", color: "yellow" },
];

const fruits = [{ name: "maçã", color: "red" }];

function firstRed(): string {
  for (const fruit of fruits) {
    if (fruit.color === "red") {
      return fruit.name;
    }
  }
  return "nenhuma";
}
